} from "@/lib/marketing/gameLocationLandings";

/**
 * Programmatic "(location) (service)" marketing landing pages, the region-tier
 * umbrella pages above them, AND (added here) the game-family × location
 * matrix + the general per-location VPS/Game-Server pages that don't already
 * exist via the tables above — see lib/marketing/gameLocationLandings.ts's
 * file doc for the full architecture note.
 *
 * Four data tables, one route: a slug is checked against the region matrix,
 * then the city matrix, then the game×location matrix, then the general
 * new-location matrix — in that order, so nothing here can ever shadow a
 * hand-written static marketing page (which wins at request time anyway) or
 * silently collide with an existing slug. Anything in none of the four falls
 * through to a 404. Real DB rows (VPS `Plan` or, for a game×location combo,
 * that family's real `GamePlan` rows) feed every page's pricing grid and
 * Product rich-result — nothing here is a hardcoded price.
 */

export const dynamic = "force-dynamic";

// Pre-declare every known slug across all four tables so Next can enumerate
// them at build time; unknown slugs are rejected in the page/metadata via
// notFound().
export function generateStaticParams(): Array<{ slug: string }> {
  return [...REGION_LANDING_SLUGS, ...LANDING_SLUGS, ...GAME_LOCATION_SLUGS, ...GENERAL_LOCATION_SLUGS].map((slug) => ({
    slug,
  }));
}

async function loadVpsPlans(): Promise<LandingPlan[]> {
  return db.plan.findMany({
    where: { active: true },
    orderBy: { sortOrder: "asc" },
  });
}

/**
 * Real, active `GamePlan` rows for one family, mapped both to the plain
 * `GamePlanRow[]` the copy builder reads for prose (RAM/slots/price only)
 * and to full `PlanCard[]` for the pricing grid — `bandwidthTB`/`storageTier`
 * come from each row's real `basePlan` (the actual VPS-grade Plan the game
 * server is provisioned on), never a fabricated number.
 */
async function loadGamePlans(gameFamily: string): Promise<{ rows: GamePlanRow[]; cards: PlanCard[] }> {
  const plans = await db.gamePlan.findMany({
    where: { gameFamily, active: true },
    orderBy: { sortOrder: "asc" },
    include: { basePlan: true },
  });
  const rows: GamePlanRow[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    ramMB: p.ramMB,
    slots: p.slots,
    priceCents: p.priceCents,
    introPriceCents: p.introPriceCents,
  }));
  const cards: PlanCard[] = plans.map((p) => ({
    id: p.id,
    name: p.name,
    cpuCores: p.cpuCores,
    ramMB: p.ramMB,
    diskGB: p.diskGB,
    bandwidthTB: p.basePlan.bandwidthTB,
    priceCents: p.priceCents,
    storageTier: p.basePlan.storageTier,
    introMonthlyCents: p.introPriceCents,
    slots: p.slots,
  }));
  return { rows, cards };
}

/**
 * Discriminant is NOT "does this page's service key happen to be `game`" —
 * the pre-existing city/region/general-location "game server hosting" pages
 * (e.g. "toronto-game-server-hosting") already price themselves off generic
 * VPS `Plan` rows (same as every other service on those tables) and deploy
 * as `service=vps`, unchanged from before this file existed. Only a genuine
 * per-family combo (e.g. "singapore-minecraft-server-hosting", resolved via
 * `findGameLocationCombo`) prices off that family's real `GamePlan` rows and
 * needs `service="game"` + `gameFamily` wired through to the deploy links.
 */
type Resolved =
  | { kind: "generic"; built: BuiltLanding; plans: LandingPlan[] }
  | {
      kind: "game-family";
      built: BuiltLanding;
      plans: PlanCard[];
      gameFamily: string;
      productName: string;
      /**
       * The GameLandingCombined-ready merge (real pricing + this combo's
       * honesty framing over the game's PREVIEW_GAMES fixture) — see
       * lib/marketing/gameLocationLandings.ts's buildGameLocationPreviewGame
       * doc. `undefined` only if `family` somehow has no PREVIEW_GAMES entry
       * (shouldn't happen for anything in ACTIVE_GAME_FAMILIES), in which case
       * the page below falls back to the generic UseCaseLanding render so a
       * drift between the two lists degrades gracefully instead of 500ing.
       */
      previewGame: PreviewGame | undefined;
    };

async function resolve(slug: string): Promise<Resolved | undefined> {
  const regionCombo = findRegionCombo(slug);
  if (regionCombo) {
    const plans = await loadVpsPlans();
    return { kind: "generic", built: buildRegionLanding(regionCombo, plans), plans };
  }

  const combo = findCombo(slug);
  if (combo) {
    const plans = await loadVpsPlans();
    return { kind: "generic", built: buildLanding(combo, plans), plans };
  }

  const generalCombo = findGeneralLocationCombo(slug);
  if (generalCombo) {
    const plans = await loadVpsPlans();
    return { kind: "generic", built: buildGeneralLocationLanding(generalCombo, plans), plans };

/**
 * Game family × location landing pages — the SEO matrix crossing every real,
 * currently-sellable game family against a country/region-level location
 * list ("Singapore Minecraft Server Hosting", "Germany Valheim Server
 * Hosting"), plus general "[Location] VPS Hosting" / "[Location] Game Server
 * Hosting" pages for the locations that don't already have an equivalent
 * page via lib/marketing/locationLandings.ts's existing city/region matrix.
 *
 * ARCHITECTURE: deliberately modeled on `buildLanding`/`buildRegionLanding`
 * in locationLandings.ts (same file this reuses `BuiltLanding`, `listPhrase`
 * and the `presence`-driven honesty discipline from) rather than the 40
 * hand-written `*-server-hosting/page.tsx` files — one data table here, wired
 * into the SAME `app/(marketing)/[slug]/page.tsx` route and the SAME
 * `app/sitemap.ts` loop as the rest of the location matrix, so there is still
 * exactly one route file and the sitemap can never drift from the real slug
 * list. Real pricing is NEVER hardcoded here: every combo's `GamePlanRow[]`
 * (or VPS `LandingPlan[]` for the general pages) is fetched live by the route
 * from `db.gamePlan` / `db.plan` and passed in — this module only turns
 * already-real numbers into prose and a spec note.
 *
 * HONESTY. Nxeon operates exactly two real datacenters — Singapore (`sgp1`)
 * and Falkenstein, Germany (`fsn1`) — see lib/node-regions.ts. Every
 * `GameLocationDef` below carries the same `presence` field as
 * `LocationDef` in locationLandings.ts ("datacenter" | "network" | "market"),
 * set from real geography, not marketing convenience:
 *   - "datacenter": Singapore, Germany (the two real DCs), plus Southeast
 *     Asia and Europe — the immediate regions those two DCs physically sit
 *     inside, so the same honest claim applies at one level up.
 *   - "network": Malaysia, Indonesia, United Kingdom, Netherlands — genuinely
 *     close to Singapore or Germany (real-world round-trip roughly within
 *     the ~40ms "low-ping" bar), so a latency-benefit claim is honestly
 *     grounded, but there is no on-site presence — never claim one.
 *   - "market": United States, North America, Canada, South Korea, Japan,
 *     India, Australia — neither real DC is genuinely close to these
 *     (measured round-trip is 70-250ms either way, per the 2026-09-24 SEO
 *     audit — South Korea/Japan/India/Australia were previously misclassified
 *     "network" on a same-continent-as-Singapore assumption that doesn't
 *     survive an actual ping test); copy here is audience-first only
 *     ("served from Singapore or Germany, pick your nearest region at
 *     checkout, test your own round-trip"), never a blanket latency claim.
 * `gameServerLocationFaq` below is the direct analogue of
 * locationLandings.ts's `serverLocationFaq` — same branch, same refusal to
 * imply a datacenter that doesn't exist.
 */
import type { GameFamily } from "@/lib/games";
import { GAME_DISPLAY, GAME_GENRES } from "@/lib/games";
import { flagEmoji } from "@/lib/flag-emoji";
