import type { MetadataRoute } from "next";
import { db } from "@/lib/db";
import { TOOL_SLUGS } from "@/lib/tools/catalog";
import { LANDING_SLUGS, REGION_LANDING_SLUGS } from "@/lib/marketing/locationLandings";
import { GAME_LOCATION_SLUGS, GENERAL_LOCATION_SLUGS } from "@/lib/marketing/gameLocationLandings";
import { countIndexableMods, listIndexableModSlugsChunk, modChunkCountFor } from "@/lib/sitemap-mods";

const APP_URL = process.env.APP_URL ?? "https://nxeon.cloud";

export const dynamic = "force-dynamic";

/**
 * Sitemap INDEX split — see lib/sitemap-mods.ts's header for the full
 * rationale (Google's real 50,000-URL-per-file cap, breached the moment the
 * ~45,761 NxLabs mod URLs shared one file with the ~1,460 other marketing
 * routes). `id: 0` is every non-mod route this file used to return in one
 * flat array — unchanged content, just no longer sharing a file with mod
 * URLs. `id: 1..N` are mod URL chunks of `MOD_SITEMAP_CHUNK_SIZE` each,
 * computed fresh every call so the id list — and therefore the real
 * `<sitemapindex>` at /sitemap.xml (app/sitemap.xml/route.ts) — always
 * matches the live catalogue size, growing automatically as more mods are
 * imported rather than needing a manual bump.
 *
 * Resulting URLs: /sitemap/0.xml (static), /sitemap/1.xml..N.xml (mods).
 * Next.js does NOT build a combined /sitemap.xml index automatically once
 * generateSitemaps() is present (confirmed against the installed next@15.5.21
 * — see app/sitemap.xml/route.ts's header) — that index is hand-written
 * there instead, listing exactly these same ids.
 */
export async function generateSitemaps(): Promise<Array<{ id: number }>> {
  const modCount = await countIndexableMods();
  const modChunks = modChunkCountFor(modCount);
  return Array.from({ length: modChunks + 1 }, (_, i) => ({ id: i }));
}

/**
 * `<lastmod>` for routes whose content isn't row-backed (the static marketing
 * pages, the hub pages, the generated location landings).
 *
 * This is deliberately NOT `new Date()`. The route is force-dynamic, so a
 * request-time timestamp made every one of the ~47,000 URLs claim it had
 * changed the instant Google fetched the file — a fresh value on every single
 * crawl, for pages that had not changed at all. Google's own guidance is that
 * it ignores (and distrusts) `lastmod` when it can't be trusted, so the signal
 * was worse than useless: it burned crawl budget re-fetching unchanged pages
 * and devalued the dates on the pages that DO carry a real one.
 *
 * These pages change when the code changes, so the deploy's own build stamp is
 * the honest answer. BUILD_TIME is written at build time by next.config.ts;
 * the fallback keeps the value stable within a process rather than per-request.
 */
const BUILD_STAMP = new Date(process.env.BUILD_TIME ?? process.env.NEXT_PUBLIC_BUILD_TIME ?? Date.now());

export default async function sitemap({ id }: { id?: string | number } = {}): Promise<MetadataRoute.Sitemap> {
  const chunkId = Number(id ?? 0);
  const now = BUILD_STAMP;

  // ── Mod URL chunks (id 1..N) ─────────────────────────────────────────
  if (chunkId > 0) {
    const modSlugs = await listIndexableModSlugsChunk(chunkId - 1);
    return modSlugs.map((m) => ({
      url: `${APP_URL}/mods/${m.family}/${m.slug}`,
      // The mod's own last-changed date, not the crawl time.
      lastModified: m.lastModified,
      changeFrequency: "weekly" as const,
      priority: 0.5,
    }));
  }

  // ── Everything else (id 0) — unchanged from the original single-file
  // sitemap, just no longer sharing a file with the mod URLs above. ─────

  const staticRoutes: Array<{ path: string; priority: number; freq: MetadataRoute.Sitemap[number]["changeFrequency"] }> = [
    // "/" not "" — an empty path emitted <loc>https://nxeon.cloud</loc> with no
    // path component at all. Google normalises that to the trailing-slash form
    // anyway, but several third-party validators flag it and there is no reason
    // for the canonical homepage entry to be the one line that needs excusing.
    { path: "/", priority: 1.0, freq: "weekly" },
    { path: "/features", priority: 0.8, freq: "monthly" },
    { path: "/vibe-coding", priority: 0.8, freq: "monthly" },
    { path: "/matrix", priority: 0.9, freq: "monthly" },
    { path: "/pricing", priority: 0.9, freq: "weekly" },
    { path: "/vps", priority: 0.8, freq: "monthly" },
    { path: "/web-hosting", priority: 0.8, freq: "monthly" },
    { path: "/domains", priority: 0.8, freq: "monthly" },
    // Core product / landing pages that shipped after the original list was
    // written — all indexable (unlike the noindex /v2–/v8 homepage previews).
    { path: "/business-email", priority: 0.8, freq: "monthly" },
    { path: "/game-servers", priority: 0.8, freq: "monthly" },
    { path: "/game-servers/mods", priority: 0.7, freq: "monthly" },
    { path: "/free-minecraft", priority: 0.8, freq: "monthly" },
    { path: "/servers", priority: 0.7, freq: "daily" },
    { path: "/block-storage", priority: 0.8, freq: "monthly" },
    { path: "/nxcloud", priority: 0.7, freq: "monthly" },
    { path: "/docs", priority: 0.6, freq: "weekly" },
    { path: "/migrate", priority: 0.7, freq: "monthly" },
