  // — e.g. /singapore-minecraft-server-hosting, /germany-valheim-server-hosting.
  // Slightly lower priority than the flagship single-game pages (0.7-0.8 above)
  // since these are the longer-tail cross-product of the two axes.
  for (const slug of GAME_LOCATION_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
      changeFrequency: "monthly",
