  // the tables above (Singapore/Germany/Europe are skipped there — already
  // covered by RESERVED_SLUGS / COMBOS / REGION_COMBOS respectively).
  for (const slug of GENERAL_LOCATION_SLUGS) {
    entries.push({
      url: `${APP_URL}/${slug}`,
      lastModified: now,
