        url: `${APP_URL}/servers/${s.subdomain}`,
        lastModified: s.createdAt,
        changeFrequency: "weekly",
        priority: 0.5,
      });
    }
  } catch {
    // Defensive, matching the blogPost handling above — should never actually
    // throw since FreeMinecraftServer ships in this same migration.
  }

