  // (lib/mods-catalog.ts's active+upstreamOk filter) are NOT pushed here —
  // they're served through their own chunked sitemap ids above/at
  // lib/sitemap-mods.ts, kept off this file entirely so this sitemap can
  // never approach Google's 50,000-URL cap again regardless of how large the
  // catalogue grows.
  entries.push({ url: `${APP_URL}/mods`, lastModified: now, changeFrequency: "weekly", priority: 0.7 });

  return entries;
}

